import json, os
import networkx as nx
from sage.all import matrix, vector, QQ

def exactR(G,s,t):
    vs=[v for v in G if v!=t]; inds={v:i for i,v in enumerate(vs)}
    L=matrix(QQ,len(vs))
    for u in vs:
      L[inds[u],inds[u]]=G.degree(u)
      for v in G[u]:
        if v!=t:L[inds[u],inds[v]]=-1
    rhs=vector(QQ,[int(u==s) for u in vs])
    return L.solve_right(rhs)[inds[s]]

for n,d in [(15,4),(17,4),(19,4),(21,4),(23,4),(25,4),(27,4),(29,4),(10,3),(12,3),(20,3)]:
 with open('best_%s_%s.json'%(n,d)) as f:r=json.load(f)
 G=nx.Graph();G.add_nodes_from(range(n));G.add_edges_from(r['edges'])
 assert nx.is_connected(G) and set(dict(G.degree()).values())=={d}
 R=exactR(G,0,n-1)
 print(n,d,'exact',R,'articulations',list(nx.articulation_points(G)),'block sizes',sorted(map(len,nx.biconnected_components(G))),'bridges',len(list(nx.bridges(G))))

